package net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.step;

import java.util.Arrays;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;

import org.apache.commons.text.StringEscapeUtils;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.feature.oauth.authentication.domain.exception.AuthenticationException;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.AuthorizeHtml;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.OidcCookieManager;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.OidcStep;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.SecureHtmlBuilder;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.SecureHtmlBuilder.EncrytFieldTransfer;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.StepInput;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.StepOutcome;
import net.civeira.phylax.feature.oauth.delegatelogin.application.DelegateLogin;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.DelegatedAccessExternalProvider;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.DelegatedProviderDescription;
import net.civeira.phylax.feature.oauth.magiclink.application.usecase.requestmagiclink.RequestMagicLinkUsecase;
import net.civeira.phylax.feature.oauth.theme.domain.gateway.DecoratePageGateway;
import net.civeira.phylax.feature.oauth.tokensecurity.application.AcrPolicy;

/**
 * Renders the primary login form for the OIDC authorization flow.
 *
 * <p>
 * Responsibilities: build the login HTML with delegated-provider buttons, recover link, and
 * register link based on tenant configuration.
 *
 * <p>
 * Design notes: isolated from routing and authentication logic — only handles presentation.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class LoginStep implements OidcStep {

  private static final String USERNAME = "username";

  private final SecureHtmlBuilder securer;
  private final DecoratePageGateway decorator;
  private final OidcCookieManager cookieManager;
  private final RecoverStep recoverStep;
  private final RegistrationStep registrationStep;
  private final DelegateLogin delegateLogin;
  private final RequestMagicLinkUsecase magicLink;
  private final AcrPolicy acrPolicy;

  @Override
  public AuthenticationChallenge challenge() {
    return null;
  }

  @Override
  public Class<? extends AuthenticationException> challengeException() {
    return null;
  }

  @Override
  public Set<String> stepNames() {
    return Set.of();
  }

  @Override
  public Set<String> initialStepNames() {
    return Set.of("login");
  }

  @Override
  public Response paint(StepInput input, NewCookie preSession) {
    throw new IllegalStateException("LoginStep is not triggered by a challenge exception");
  }

  @Override
  public Optional<StepOutcome> process(StepInput input) {
    return Optional.empty();
  }

  @Override
  public Optional<Response> paintInitial(StepInput input, String error) {
    return Optional.of(paintForm(input.getRequest(), error));
  }

  /**
   * Translation of a key, or the fallback when the messages of the tenant do not have it yet.
   *
   * @param locale locale of the page
   * @param key message key
   * @param fallback text used when the key is missing
   * @return the text
   */
  public static String text(Locale locale, String key, String fallback) {
    String value = AuthorizeHtml.i18n(locale, key);
    return value == null || value.equals(key) ? fallback : value;
  }

  /**
   * Sign-in with a passkey: hidden until {@code webauthn.js} sees that the browser supports it,
   * then posted with the assertion as {@code step=webauthn-login}.
   */
  private String passkeyForm(AuthRequest request) {
    Locale locale = request.getLocale();
    String begin = "/oauth/openid/" + request.getTenant() + "/webauthn/authenticate/begin";
    return "<form method=\"POST\" class=\"passkey-login\" data-webauthn-login"
        + " style=\"display:none\" data-begin=\"" + StringEscapeUtils.escapeHtml4(begin)
        + "\" data-error=\""
        + StringEscapeUtils
            .escapeHtml4(text(locale, "login.passkey-failed", "The passkey could not be verified"))
        + "\">" + "<input type=\"hidden\" name=\"step\" value=\"" + WebAuthnLoginStep.STEP + "\" />"
        + "<input type=\"hidden\" name=\"csid\" />"
        + "<input type=\"hidden\" name=\"challengeId\" />"
        + "<input type=\"hidden\" name=\"credential\" />"
        + "<p><button type=\"button\" class=\"secondary-button passkey-button\""
        + " data-webauthn-login-button>"
        + StringEscapeUtils
            .escapeHtml4(text(locale, "login.passkey-label", "Sign in with a passkey"))
        + "</button></p>" + "<p class=\"error\" data-webauthn-error style=\"display:none\"></p>"
        + "</form>" + "<script src=\"/oauth/assets/webauthn.js\"></script>";
  }

  /**
   * Renders the login form, optionally showing an error message.
   *
   * @param request current auth request (used for locale, tenant, client label)
   * @param error optional error message to display; {@code null} for no error
   * @return 200 HTML response with cleared session cookies
   */
  public Response paintForm(AuthRequest request, String error) {
    Locale locale = request.getLocale();
    String js = securer.configureScripts(securer.focusOn(USERNAME), securer.addSign("sign"),
        securer.cypher(
            Arrays
                .asList(EncrytFieldTransfer.builder().from("type_password").to("password").build()),
            "login"));

    String title = AuthorizeHtml.i18n(locale, "login.title");
    String errorMsg = AuthorizeHtml.i18n(locale, "login.error-format", error);
    String help = AuthorizeHtml.i18n(locale, "login.help", request.getTenant());
    String usernameLabel = AuthorizeHtml.i18n(locale, "login.username");
    String passwordLabel = AuthorizeHtml.i18n(locale, "login.password");
    String recoverLabel = AuthorizeHtml.i18n(locale, "login.recover-label");
    String recoverText = "<input class=\"inline\" type=\"submit\" value=\"" + recoverLabel + "\"/>";
    String magicLinkLabel = AuthorizeHtml.i18n(locale, "login.magic-link-label");
    String magicLinkText =
        "<input class=\"inline\" type=\"submit\" value=\"" + magicLinkLabel + "\"/>";
    String enter = AuthorizeHtml.i18n(locale, "login.enter");

    StringBuilder delegatedLogins = new StringBuilder();
    StringBuilder execAuto = new StringBuilder();

    for (DelegatedAccessExternalProvider provider : delegateLogin.providers(request)) {
      DelegatedProviderDescription info = provider.info(request);
      delegatedLogins.append("                    <form method=\"POST\" id=\"social-form-"
          + info.getId() + "\" class=\"social-form\">\r\n"
          + "                        <input type=\"hidden\" name=\"step\" value=\"delegated-login\" />"
          + "                        <input type=\"hidden\" name=\"delegated-provider\" value=\""
          + info.getId() + "\" />"
          + "                        <button type=\"submit\" class=\"social-button\">\r\n"
          + "                            <img src=\"" + info.getLogo() + "\" alt=\""
          + info.getName() + "\">\r\n" + "                        </button>\r\n"
          + "                    </form>\r\n");
      if (info.isAutomatic()) {
        execAuto.append(
            "<script>" + "document.addEventListener('DOMContentLoaded', function(event) {\r\n"
                + "document.getElementById(\"social-form-" + info.getId() + "\").submit();" + "});"
                + "</script>");
      }
    }

    if (!delegatedLogins.isEmpty()) {
      delegatedLogins.append(
          " <div class=\"social-login-buttons\">\r\n" + "" + delegatedLogins + "" + "</div>");
    }

    return securer.secureHtmlResponse(Response.ok(decorator.getFullPage(request.getTenant(),
        "Login",
        js + "<h1>" + title + "</h1>" + "<p>" + help + "</p>"
            + (null == error ? "" : "<p class=\"error\">" + errorMsg + "</p>")
            + "<form id=\"login\" method=\"POST\">"
            + "<input type=\"hidden\" name=\"csid\" id=\"sign\" />" + "<label>" + usernameLabel
            + " <input type=\"text\" id=\"username\" name=\"username\""
            + " autocomplete=\"username webauthn\" value=\""
            + StringEscapeUtils.escapeHtml4(request.getLoginHint().orElse("")) + "\" /></label>"
            + "<label>" + passwordLabel + " <input type=\"password\" id=\"type_password\" value=\""
            + "\" /></label>" + "<input type=\"hidden\" id=\"password\" name=\"password\" value=\""
            + "\" />" + "<input class=\"primary-button action-button\" type=\"submit\" value=\""
            + enter + "\" />" + "</form>" + passkeyForm(request) + delegatedLogins + execAuto
            + (recoverStep.allowRecover(request.getTenant()) ? "<form method=\"POST\">"
                + "<input type=\"hidden\" name=\"step\" value=\"show-recover\" />" + "<p>"
                + recoverText + "</p></form>" : "")
            + (registrationStep.selfRegistrationEnabled(request.getTenant())
                ? "<form method=\"POST\">"
                    + "<input type=\"hidden\" name=\"step\" value=\"show-register\" />" + "<p>"
                    + "<input class=\"inline\" type=\"submit\" value=\""
                    + AuthorizeHtml.i18n(locale, "login.register-label") + "\"/>" + "</p></form>"
                : "")
            // No sign-in link when the request asks for a second factor (task 3.10).
            + (magicLink.isEnabled(request.getTenant())
                && !acrPolicy.requiresMultiFactor(request.getAcrValues().orElse(null))
                    ? "<form method=\"POST\">"
                        + "<input type=\"hidden\" name=\"step\" value=\"show-magic-link\" />"
                        + "<p>" + magicLinkText + "</p></form>"
                    : ""),
        locale)).type(AuthorizeHtml.TEXT_HTML)
        .cookie(cookieManager.clearAuthSession(request.getTenant()))
        .cookie(cookieManager.clearPreSession(request.getTenant())));
  }
}
